WITH RECURSIVE department_paths AS ( SELECT id AS department_id, parent_id, CAST(CONCAT('0,', id) AS CHAR(500)) AS visited_path FROM sys_dept WHERE id IN
#{departmentId}
AND deleted = 0 AND status = 0 UNION ALL SELECT path.department_id, parent.parent_id, CONCAT(path.visited_path, ',', parent.id) FROM department_paths path INNER JOIN sys_dept parent ON parent.id = path.parent_id AND parent.deleted = 0 AND parent.status = 0 WHERE path.parent_id != 0 AND FIND_IN_SET(parent.id, path.visited_path) = 0 AND CHAR_LENGTH(path.visited_path) + CHAR_LENGTH(CAST(parent.id AS CHAR)) + 1 <= 500 ) SELECT department_id FROM department_paths WHERE parent_id = 0
